import sys, os, unittest
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from shop.pricing import apply_tax


class TestApplyTax(unittest.TestCase):
    def test_default_rate_rounds_to_cents(self):
        self.assertEqual(apply_tax(19.99), 21.39)

    def test_custom_rate(self):
        self.assertEqual(apply_tax(100, 0.2), 120.0)

    def test_zero_amount(self):
        self.assertEqual(apply_tax(0), 0)


if __name__ == "__main__":
    unittest.main()

